        class="sui-social-link sui-social-link--<?= h($platform) ?>"
        target="_blank"
        rel="noopener noreferrer"
        aria-label="<?= h($link['label'] ?: ucfirst($platform)) ?>"
        role="listitem"
        style="display:inline-flex;align-items:center;justify-content:center;width:<?= $iconSize ?>;height:<?= $iconSize ?>;border-radius:var(--radius-full);background:var(--color-bg-elevated);border:1px solid var(--color-border);color:var(--color-text-muted);transition:background var(--transition-fast),color var(--transition-fast),border-color var(--transition-fast);"
