    >
        <?= $svg ?>
        <?php if ($style === 'icon-label'): ?>
        <span style="margin-left:var(--space-2);font-size:var(--font-size-sm);"><?= h($link['label'] ?: ucfirst($platform)) ?></span>
        <?php endif; ?>
    </a>
    <?php endforeach; ?>
</div>
